def transform(grid):
    g=[r[:] for r in grid]
    # Color 8 indicates the endpoints of each 2-pattern stroke: transform
    # the first and last occupied cells of each connected shape.
    H=len(g); W=len(g[0]); seen=set()
    for r in range(H):
        for c in range(W):
            if g[r][c]!=2 or (r,c) in seen: continue
            comp=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<H and 0<=b<W and g[a][b]==2 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            # endpoints are cells with exactly one neighbor within component
            ends=[]
            for x,y in comp:
                deg=sum((a,b) in comp for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)))
                if deg<=1: ends.append((x,y))
            for x,y in ends: g[x][y]=8
    # remove 3-colored separator and reproduce the nearby motif into it by
    # reflection across the separator; simpler: preserve colors otherwise
    for x in range(H):
        for y in range(W):
            if g[x][y]==3: g[x][y]=0
    return g
